import hashlib
import json
from pathlib import Path

folder = Path('products/distribution/catalogue-editor-example-placement')
expected = '8bb6898a489669b02cd4db20f10abbe524a2d87b4c4590d233b49d337eb83bcc'
files = {'live_capture': folder / 'live-baseline.html', 'checkout': Path('products/sites/shopify-catalogue-example/index.html')}
checks = {}
for label, path in files.items():
    digest = hashlib.sha256(path.read_bytes()).hexdigest() if path.is_file() else None
    checks[label] = {'path': str(path), 'sha256': digest, 'matches_fetch_receipt': digest == expected}
result = {'fetch_receipt': 'TASK-179528221300', 'expected_sha256': expected, 'checks': checks, 'baseline_match': all(item['matches_fetch_receipt'] for item in checks.values())}
folder.mkdir(parents=True, exist_ok=True)
artifact = folder / 'live-checkout-comparison.json'
artifact.write_text(json.dumps(result, indent=2) + '\n', encoding='utf-8')
print(artifact.read_text(encoding='utf-8'))
